break;case 'day_close':case 'day_reopen':fi('Review Date','date',is_string($_GET['id']??null)?$_GET['id']:$date,'date');fi('Review / Reopening Comment','comment','','text',false);
break;case 'period_lock':case 'period_reopen':?><input type="hidden" name="period" value="<?=access_h($period)?>"><input type="hidden" name="start" value="<?=access_h($start)?>"><p><?=access_h(ucfirst($period).' starting '.$start)?></p><?php fi('Review / Reopening Comment','comment');if($form==='period_lock'){fc('I reviewed missing costs, payroll, invoices, receipts and the stated revenue limitations.','complete');}
break;case 'income_record':fi('Payer Name','payer');fi('Phone Number (Optional)','phone','','tel',false);fi('Activity / Service','activity');fi('Amount Received (GHS)','amount');?><label>Payment Method<select name="method"><option value="cash">Cash</option><option value="momo">MoMo</option></select></label><label>Payment For<select name="treatment"><option value="earned">Service Already Provided</option><option value="advance">Advance For A Future Activity</option></select></label><?php fi('Payment Reference (Optional)','reference','','text',false);?><label class="finance-check"><input type="checkbox" name="provided" value="1"> The activity or service has already been provided (required for completed-service revenue).</label><p>Cash receipts must be deposited in full by the next day. Advances count as money received and become revenue only when service delivery is recorded.</p><?php
break;case 'income_complete':fc('The activity or service has now been provided.','provided');fi('Comment (Optional)','comment','','text',false);
break;case 'review_action':fi('Action','comment');fi('Action Owner','owner');fi('Due Date','due',$today,'date');break;endswitch?>
<?php if(in_array($form,['pay_cost','income_record'],true)&&$s->canPostLate($actor)):?>
<details><summary>Record Late Payment</summary><p>Enter the actual payment date and transaction reference. The entry posts today if today's accounting period is open.</p>
<?php fi('Original activity date','original_activity_date','','date',false);fi('Late posting reason','late_reason','','text',false);?>
</details>
<?php endif?>
