<?php if(in_array($page,['daily','profit'],true)):?><section class="card"><h2>Retained Review History</h2><?php foreach(array_reverse($events) as $e):if(!in_array($e['kind'],$page==='daily'?['day_closed','day_reopened']:['period_locked','period_reopened','review_action'],true)||($e['data']['workflow']??'')==='weekly_reconciliation')continue;?><details><summary>#<?=(int)$e['id']?> · <?=access_h(ucwords(str_replace('_',' ',$e['kind'])).' · '.$e['target_id'].' · '.$e['actor_name'].' · '.display_date($e['created_at']))?></summary><pre><?=access_h(json_encode($e['data'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details><?php endforeach?></section><?php endif?>
